<script>
function overCountry(countryName) {
    let tooltipCountry = document.getElementById("tooltipCountry");
    tooltipCountry.style.display = "block";
    tooltipCountry.style.left = event.pageX + "px";
    tooltipCountry.style.top = event.pageY + "px";
    tooltipCountry.textContent = countryName;
}
function outCountry() {
    document.getElementById("tooltipCountry").style.display = "none";
}
</script>
<script>
  document.getElementById('worldMap').addEventListener('click', function(event) {
    const rect = this.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    document.getElementById('coordinates').textContent = `Coordinates: (${x}, ${y})`;
  });
</script>
